   678	int nxcamera_stop(FAR struct nxcamera_s *pcam)
   679	{
   680	  struct video_msg_s term_msg;
   681	
   682	  DEBUGASSERT(pcam != NULL);
   683	
   684	  /* Validate we are not in IDLE state */
   685	
   686	  pthread_mutex_lock(&pcam->mutex);          /* Lock the mutex */
   687	  if (pcam->loopstate == NXCAMERA_STATE_IDLE)
   688	    {
   689	      pthread_mutex_unlock(&pcam->mutex);    /* Unlock the mutex */
   690	      return OK;
   691	    }
   692	
   693	  /* Notify the stream thread that it needs to cancel the stream */
   694	
   695	  term_msg.msg_id = VIDEO_MSG_STOP;
   696	  term_msg.u.data = 0;
   697	  mq_send(pcam->mq, (FAR const char *)&term_msg, sizeof(term_msg),
   698	          CONFIG_NXCAMERA_MSG_PRIO);
   699	
   700	  pthread_mutex_unlock(&pcam->mutex);
   701	
   702	  /* Join the thread.  The thread will do all the cleanup. */
   703	
   704	  nxcamera_jointhread(pcam);
   705	
   706	  return OK;

